begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","app_metadata":{"role":"project_engineer"}}',true);
select lives_ok($test$select public.v1_save_calculator('{"id": "47000000-0000-4000-8000-000000000001", "title": "General duct", "kind": "duct", "expected_version": 0, "payload": {"app": "duct-calc", "version": 1, "flow": "1000", "future": {"kept": true}}}'::jsonb,'48000000-0000-4000-8000-000000000001')$test$,'Project Engineer creates a general calculation');
select lives_ok($test$select public.v1_save_calculator('{"id": "47000000-0000-4000-8000-000000000001", "title": "General duct", "kind": "duct", "expected_version": 0, "payload": {"app": "duct-calc", "version": 1, "flow": "1000", "future": {"kept": true}}}'::jsonb,'48000000-0000-4000-8000-000000000001')$test$,'Same intent safely replays');
select is((select public.v1_get_calculator('47000000-0000-4000-8000-000000000001')->>'record_version'),'1'::text,'Replay does not advance revision');
select is((select public.v1_get_calculator('47000000-0000-4000-8000-000000000001')->'payload'->'future'),'{"kept":true}'::jsonb,'Unknown fields retained');
select throws_ok($test$select public.v1_save_calculator('{"id": "47000000-0000-4000-8000-000000000001", "title": "changed", "kind": "duct", "expected_version": 0, "payload": {"app": "duct-calc", "version": 1, "flow": "1000", "future": {"kept": true}}}'::jsonb,'48000000-0000-4000-8000-000000000001')$test$,'22023','V1_IDEMPOTENCY_KEY_REUSED_WITH_DIFFERENT_PAYLOAD','Key payload mismatch rejected');
select throws_ok($test$select public.v1_save_calculator('{"id": "47000000-0000-4000-8000-000000000001", "title": "General duct", "kind": "duct", "expected_version": 0, "payload": {"app": "duct-calc", "version": 1, "flow": "1000", "future": {"kept": true}}}'::jsonb,'48000000-0000-4000-8000-000000000002')$test$,'40001','CALCULATOR_VERSION_CONFLICT','Stale revision rejected');
select throws_ok($test$select public.v1_manage_calculator('{"id": "47000000-0000-4000-8000-000000000001", "expected_version": 1, "action": "access", "user_id": "10000000-0000-4000-8000-000000000002", "access": "edit"}'::jsonb,'49000000-0000-4000-8000-000000000001')$test$,'42501','CALCULATOR_ACCESS_DENIED','Owner cannot grant access without manager role');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated","app_metadata":{"role":"site_engineer"}}',true);
select throws_ok($test$select public.v1_get_calculator('47000000-0000-4000-8000-000000000001')$test$,'42501','CALCULATOR_ACCESS_DENIED','Unshared Site Engineer denied');
select is((select jsonb_array_length(public.v1_list_calculators(p_search=>'General duct')->'items')),0,'Unauthorized record absent from library');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000003","role":"authenticated","app_metadata":{"role":"procurement"}}',true);
select throws_ok($test$select public.v1_save_calculator('{"id": "47000000-0000-4000-8000-000000000002", "title": "General duct", "kind": "duct", "expected_version": 0, "payload": {"app": "duct-calc", "version": 1, "flow": "1000", "future": {"kept": true}}}'::jsonb,'48000000-0000-4000-8000-000000000003')$test$,'42501','CALCULATOR_ACCESS_DENIED','Procurement cannot create calculators');
select throws_ok($test$select * from public.v1_calculators$test$,'42501','permission denied for table v1_calculators','Direct table reads denied');
select throws_ok($test$select public.v1_calculator_json('47000000-0000-4000-8000-000000000001')$test$,'42501','permission denied for function v1_calculator_json','Projection helper inaccessible');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000004","role":"authenticated","app_metadata":{"role":"admin"}}',true);
select lives_ok($test$select public.v1_manage_calculator('{"id": "47000000-0000-4000-8000-000000000001", "expected_version": 1, "action": "access", "user_id": "10000000-0000-4000-8000-000000000002", "access": "view"}'::jsonb,'49000000-0000-4000-8000-000000000002')$test$,'Admin grants view');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated","app_metadata":{"role":"site_engineer"}}',true);
select lives_ok($test$select public.v1_get_calculator('47000000-0000-4000-8000-000000000001')$test$,'Granted viewer can read');
select throws_ok($test$select public.v1_save_calculator('{"id": "47000000-0000-4000-8000-000000000001", "title": "General duct", "kind": "duct", "expected_version": 2, "payload": {"app": "duct-calc", "version": 1, "flow": "1000", "future": {"kept": true}}}'::jsonb,'48000000-0000-4000-8000-000000000004')$test$,'42501','CALCULATOR_ACCESS_DENIED','Viewer cannot edit');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000004","role":"authenticated","app_metadata":{"role":"admin"}}',true);
select lives_ok($test$select public.v1_manage_calculator('{"id": "47000000-0000-4000-8000-000000000001", "expected_version": 2, "action": "access", "user_id": "10000000-0000-4000-8000-000000000002", "access": "edit"}'::jsonb,'49000000-0000-4000-8000-000000000003')$test$,'Admin grants edit');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated","app_metadata":{"role":"site_engineer"}}',true);
select lives_ok($test$select public.v1_save_calculator('{"id": "47000000-0000-4000-8000-000000000001", "title": "Site revised", "kind": "duct", "expected_version": 3, "payload": {"app": "duct-calc", "version": 1, "flow": "1000", "future": {"kept": true}}}'::jsonb,'48000000-0000-4000-8000-000000000005')$test$,'Granted editor saves');
select lives_ok($test$select public.v1_save_calculator('{"id": "47000000-0000-4000-8000-000000000001", "title": "Site revised", "kind": "duct", "expected_version": 3, "payload": {"app": "duct-calc", "version": 1, "flow": "1000", "future": {"kept": true}}}'::jsonb,'48000000-0000-4000-8000-000000000005')$test$,'Editor retry idempotent');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000004","role":"authenticated","app_metadata":{"role":"admin"}}',true);
select lives_ok($test$select public.v1_manage_calculator('{"id": "47000000-0000-4000-8000-000000000001", "expected_version": 4, "action": "access", "user_id": "10000000-0000-4000-8000-000000000002", "access": "none"}'::jsonb,'49000000-0000-4000-8000-000000000004')$test$,'Manager revokes access');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated","app_metadata":{"role":"site_engineer"}}',true);
select throws_ok($test$select public.v1_get_calculator('47000000-0000-4000-8000-000000000001')$test$,'42501','CALCULATOR_ACCESS_DENIED','Revocation immediately denies reads');
select throws_ok($test$select public.v1_save_calculator('{"id": "47000000-0000-4000-8000-000000000001", "title": "Site revised", "kind": "duct", "expected_version": 3, "payload": {"app": "duct-calc", "version": 1, "flow": "1000", "future": {"kept": true}}}'::jsonb,'48000000-0000-4000-8000-000000000005')$test$,'42501','CALCULATOR_ACCESS_DENIED','Revoked editor cannot replay cached command');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000004","role":"authenticated","app_metadata":{"role":"admin"}}',true);
select lives_ok($test$select public.v1_manage_calculator('{"id": "47000000-0000-4000-8000-000000000001", "expected_version": 5, "action": "archive", "archived": true}'::jsonb,'49000000-0000-4000-8000-000000000005')$test$,'Archive retains calculation');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","app_metadata":{"role":"project_engineer"}}',true);
select throws_ok($test$select public.v1_save_calculator('{"id": "47000000-0000-4000-8000-000000000001", "title": "General duct", "kind": "duct", "expected_version": 6, "payload": {"app": "duct-calc", "version": 1, "flow": "1000", "future": {"kept": true}}}'::jsonb,'48000000-0000-4000-8000-000000000006')$test$,'55000','CALCULATOR_ARCHIVED','Archived calculation immutable');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000004","role":"authenticated","app_metadata":{"role":"admin"}}',true);
select lives_ok($test$select public.v1_manage_calculator('{"id": "47000000-0000-4000-8000-000000000001", "expected_version": 6, "action": "archive", "archived": false}'::jsonb,'49000000-0000-4000-8000-000000000006')$test$,'Restore archived calculation');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","app_metadata":{"role":"project_engineer"}}',true);
select lives_ok($test$select public.v1_create_project('{"project_ref":"CALC-TEST","name":"Calculator project","buildings":[{"code":"A","name":"Building A"}],"initial_members":[],"attachments":[]}', '48000000-0000-4000-8000-000000000010')$test$,'Create calculator project');
set local role postgres; create temp table calculator_project as select id from public.v1_projects where project_ref='CALC-TEST'; grant select on calculator_project to authenticated;
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","app_metadata":{"role":"project_engineer"}}',true);
select lives_ok($test$select public.v1_save_calculator('{"id": "47000000-0000-4000-8000-000000000002", "title": "General duct", "kind": "duct", "expected_version": 0, "payload": {"app": "duct-calc", "version": 1, "flow": "1000", "future": {"kept": true}}}'::jsonb || jsonb_build_object('project_id',(select id from calculator_project)), '48000000-0000-4000-8000-000000000011')$test$,'Create assigned project calculator');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000004","role":"authenticated","app_metadata":{"role":"admin"}}',true);
select lives_ok($test$select public.v1_manage_calculator('{"id": "47000000-0000-4000-8000-000000000002", "expected_version": 1, "action": "access", "user_id": "10000000-0000-4000-8000-000000000002", "access": "edit"}','49000000-0000-4000-8000-000000000007')$test$,'Project grant does not create membership');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated","app_metadata":{"role":"site_engineer"}}',true);
select throws_ok($test$select public.v1_get_calculator('47000000-0000-4000-8000-000000000002')$test$,'42501','CALCULATOR_ACCESS_DENIED','Calculator grant cannot bypass project access');
set local role postgres; update auth.users set raw_app_meta_data=raw_app_meta_data || jsonb_build_object('role','senior_mechanical_engineer') where id='10000000-0000-4000-8000-000000000009';
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000009","role":"authenticated","app_metadata":{"role":"senior_mechanical_engineer"}}',true);
select lives_ok($test$select public.v1_get_calculator('47000000-0000-4000-8000-000000000001')$test$,'senior_mechanical_engineer manages general calculators');
select is((select public.v1_list_calculators()->>'can_manage'),'true'::text,'senior_mechanical_engineer sharing enabled');
set local role postgres; update auth.users set raw_app_meta_data=raw_app_meta_data || jsonb_build_object('role','project_manager') where id='10000000-0000-4000-8000-000000000009';
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000009","role":"authenticated","app_metadata":{"role":"project_manager"}}',true);
select lives_ok($test$select public.v1_get_calculator('47000000-0000-4000-8000-000000000001')$test$,'project_manager manages general calculators');
select is((select public.v1_list_calculators()->>'can_manage'),'true'::text,'project_manager sharing enabled');
set local role postgres; update auth.users set raw_app_meta_data=raw_app_meta_data || jsonb_build_object('role','workshop_in_charge') where id='10000000-0000-4000-8000-000000000009';
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000009","role":"authenticated","app_metadata":{"role":"workshop_in_charge"}}',true);
select throws_ok($test$select public.v1_get_calculator('47000000-0000-4000-8000-000000000001')$test$,'42501','CALCULATOR_ACCESS_DENIED','workshop_in_charge has no implicit sharing access');
set local role postgres; update auth.users set raw_app_meta_data=raw_app_meta_data || jsonb_build_object('role','document_controller') where id='10000000-0000-4000-8000-000000000009';
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000009","role":"authenticated","app_metadata":{"role":"document_controller"}}',true);
select throws_ok($test$select public.v1_get_calculator('47000000-0000-4000-8000-000000000001')$test$,'42501','CALCULATOR_ACCESS_DENIED','document_controller has no implicit sharing access');
set local role postgres; update auth.users set raw_app_meta_data=raw_app_meta_data || jsonb_build_object('role','accountant') where id='10000000-0000-4000-8000-000000000009';
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000009","role":"authenticated","app_metadata":{"role":"accountant"}}',true);
select throws_ok($test$select public.v1_get_calculator('47000000-0000-4000-8000-000000000001')$test$,'42501','CALCULATOR_ACCESS_DENIED','accountant has no implicit sharing access');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000009","role":"authenticated","app_metadata":{"role":"senior_mechanical_engineer"}}',true);
select throws_ok($test$select public.v1_get_calculator('47000000-0000-4000-8000-000000000001')$test$,'42501','CALCULATOR_ACCESS_DENIED','Stale role JWT denied');
set local role postgres;
select is((select count(*) from public.v1_calculators where id::text like '47000000-%'),2::bigint,'No duplicate or unauthorized records');
select is((select count(*) from public.v1_audit_events where entity_type='calculator' and event_type='calculator_saved' and entity_id::text like '47000000-%'),3::bigint,'One audit per unique committed save');

set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000004","role":"authenticated","app_metadata":{"role":"admin"}}',true);
select is(jsonb_array_length(public.v1_list_calculators(p_kind=>'esp')->'items'),0,'Type filter runs before pagination');
select is((select count(*)::integer from jsonb_array_elements(public.v1_list_calculators(p_scope=>'general')->'items') r where r->>'id' like '47000000-%'),1,'General filter excludes project scope');
select throws_ok($test$select public.v1_save_calculator('{"id":"47000000-0000-4000-8000-000000000099","title":"Invalid","kind":"duct","expected_version":0,"payload":{"app":"duct-calc","version":1,"flow":"1e9999"}}'::jsonb,'48000000-0000-4000-8000-000000000099')$test$,'22023','CALCULATOR_INVALID_INPUT','Overflow cannot create an unreadable record');
select throws_ok($test$select public.v1_save_calculator('{"id":"47000000-0000-4000-8000-000000000099","title":"Invalid","kind":"esp","expected_version":0,"payload":{"app":"esp-calc","version":1,"rows":[{"id":"x","flow":"NaN"}]}}'::jsonb,'48000000-0000-4000-8000-000000000098')$test$,'22023','CALCULATOR_INVALID_INPUT','ESP malformed input rejected on server');

set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000004","role":"authenticated","app_metadata":{"role":"admin"}}',true);
select lives_ok($test$select public.v1_manage_calculator(jsonb_build_object('id','47000000-0000-4000-8000-000000000001','expected_version',(public.v1_get_calculator('47000000-0000-4000-8000-000000000001')->>'record_version')::int,'action','access','user_id','10000000-0000-4000-8000-000000000013','access','edit'),'49000000-0000-4000-8000-000000000099')$test$,'Admin can explicitly grant a general calculator to Accountant');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000013","role":"authenticated","app_metadata":{"role":"accountant"}}',true);
select lives_ok($test$select public.v1_get_calculator('47000000-0000-4000-8000-000000000001')$test$,'Explicitly granted Accountant reads this calculator');
select lives_ok($test$select public.v1_save_calculator(jsonb_build_object('id','47000000-0000-4000-8000-000000000001','expected_version',(public.v1_get_calculator('47000000-0000-4000-8000-000000000001')->>'record_version')::int,'title','Accountant scoped edit','kind','duct','payload',jsonb_build_object('app','duct-calc','version',1,'flow','1500')),'48000000-0000-4000-8000-000000000097')$test$,'Explicit edit grant allows input changes without technical role promotion');
select is(public.v1_list_calculators()->>'can_create','false','Calculator grant does not grant creation authority');
select is(public.v1_list_calculators()->>'can_manage','false','Calculator grant does not grant sharing authority');
set local role postgres;
update public.v1_profiles set is_active=false where auth_user_id='10000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated","app_metadata":{"role":"site_engineer"}}',true);
select throws_ok($test$select public.v1_list_calculators()$test$,'42501','CALCULATOR_ACCESS_DENIED','Inactive actor cannot list calculators');
select throws_ok($test$select public.v1_save_calculator('{"id":"47000000-0000-4000-8000-000000000095","title":"Inactive","kind":"duct","expected_version":0,"payload":{"app":"duct-calc","version":1,"flow":"1000"}}'::jsonb,'48000000-0000-4000-8000-000000000095')$test$,'42501','CALCULATOR_ACCESS_DENIED','Inactive actor cannot create calculators');
set local role postgres;
update public.v1_profiles set is_active=true where auth_user_id='10000000-0000-4000-8000-000000000002';
update auth.users set deleted_at=now() where id='10000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($test$select public.v1_save_calculator('{"id":"47000000-0000-4000-8000-000000000095","title":"Deleted","kind":"duct","expected_version":0,"payload":{"app":"duct-calc","version":1,"flow":"1000"}}'::jsonb,'48000000-0000-4000-8000-000000000096')$test$,'42501','CALCULATOR_ACCESS_DENIED','Soft deleted actor with retained JWT cannot create calculators');
select * from finish();
rollback;
